SELECT (?sum2019 - ?sum2020 AS ?diff)
WHERE {
  {
    SELECT (SUM(?spent) AS ?sum2019) WHERE {
      ?b a <http://bird-bird_student_club-ontology-20260809-235507/ontology/vkg-bird_student_club/Budget> ;
         <http://bird-bird_student_club-ontology-20260809-235507/ontology/vkg-bird_student_club/Budget/spent> ?spent ;
         <http://bird-bird_student_club-ontology-20260809-235507/ontology/vkg-bird_student_club/Budget/link_to_event> ?eid .
      ?e a <http://bird-bird_student_club-ontology-20260809-235507/ontology/vkg-bird_student_club/Event> ;
         <http://bird-bird_student_club-ontology-20260809-235507/ontology/vkg-bird_student_club/Event/event_id> ?eid ;
         <http://bird-bird_student_club-ontology-20260809-235507/ontology/vkg-bird_student_club/Event/event_date> ?date .
      BIND(SUBSTR(STR(?date),1,4) AS ?year)
      FILTER(?year = "2019")
    }
  }
  {
    SELECT (SUM(?spent2) AS ?sum2020) WHERE {
      ?b2 a <http://bird-bird_student_club-ontology-20260809-235507/ontology/vkg-bird_student_club/Budget> ;
          <http://bird-bird_student_club-ontology-20260809-235507/ontology/vkg-bird_student_club/Budget/spent> ?spent2 ;
          <http://bird-bird_student_club-ontology-20260809-235507/ontology/vkg-bird_student_club/Budget/link_to_event> ?eid2 .
      ?e2 a <http://bird-bird_student_club-ontology-20260809-235507/ontology/vkg-bird_student_club/Event> ;
          <http://bird-bird_student_club-ontology-20260809-235507/ontology/vkg-bird_student_club/Event/event_id> ?eid2 ;
          <http://bird-bird_student_club-ontology-20260809-235507/ontology/vkg-bird_student_club/Event/event_date> ?date2 .
      BIND(SUBSTR(STR(?date2),1,4) AS ?year2)
      FILTER(?year2 = "2020")
    }
  }
}

